import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ManagerTripApprovals = () => {
  const [pendingRequests, setPendingRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedTrip, setSelectedTrip] = useState(null);
  const [approvalNotes, setApprovalNotes] = useState('');
  const [budgetAdjustments, setBudgetAdjustments] = useState({});

  useEffect(() => { fetchPendingRequests(); }, []);

  const fetchPendingRequests = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/trip-budget/pending-requests', { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) setPendingRequests(response.data.pending_requests);
    } catch (err) {
      console.error('Error fetching pending requests:', err); setError('Failed to load pending trip requests');
    } finally { setLoading(false); }
  };

  const handleApproveTrip = async (tripId) => {
    try {
      const token = localStorage.getItem('token');
      const requestData = { trip_id: tripId, approval_notes: approvalNotes || null, budget_adjustments: Object.keys(budgetAdjustments).length > 0 ? budgetAdjustments : null };
      const response = await axios.post('http://localhost:8000/trip-budget/approve-trip', requestData, { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) { alert('Trip approved successfully!'); setSelectedTrip(null); setApprovalNotes(''); setBudgetAdjustments({}); fetchPendingRequests(); }
    } catch (err) { console.error('Error approving trip:', err); alert('Failed to approve trip: ' + (err.response?.data?.detail || err.message)); }
  };

  const handleBudgetAdjustment = (expenseType, newAmount) => { setBudgetAdjustments(prev => ({ ...prev, [expenseType]: parseFloat(newAmount) || 0 })); };
  const formatCurrency = (amount) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(amount);
  const getStatusColor = (status) => ({ pending: '#ffc107', approved: '#28a745', active: '#007bff', completed: '#6c757d', cancelled: '#dc3545' }[status] || '#6c757d');

  if (loading) return (<div className="container-page"><div className="content-card loading-container"><div className="loading-spinner"></div><p>Loading pending trip requests...</p></div></div>);
  if (error) return (<div className="container-page"><div className="content-card error-container"><h2>❌ Error</h2><p>{error}</p><button onClick={fetchPendingRequests} className="btn btn-secondary">🔄 Retry</button></div></div>);

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">👨‍💼 Trip Approval Dashboard</div>
        <div className="subtitle">Review and approve employee trip requests</div>
      </div>

      <div className="content-card">
        {pendingRequests.length === 0 ? (
          <div className="text-center text-muted">No pending requests. Check back later.</div>
        ) : (
          <div className="requests-grid">
            {pendingRequests.map((trip) => (
              <div key={trip.trip_id} className="request-card card-hover">
                <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                  <div>
                    <div className="page-title" style={{ margin: 0 }}>{trip.employee_name}</div>
                    <div className="text-muted">{trip.designation.replace('_', ' ').toUpperCase()}</div>
                  </div>
                  <span className="badge" style={{ backgroundColor: getStatusColor(trip.status) }}>{trip.status.toUpperCase()}</span>
                </div>

                <div className="section">
                  <div><strong>Purpose:</strong> {trip.purpose}</div>
                  <div><strong>Destination:</strong> {trip.destination} ({trip.destination_tier.replace('_', ' ')})</div>
                  <div><strong>Duration:</strong> {trip.duration_days} days</div>
                  <div><strong>Dates:</strong> {new Date(trip.start_date).toLocaleDateString()} - {new Date(trip.end_date).toLocaleDateString()}</div>
                  <div><strong>Total Budget:</strong> {formatCurrency(trip.total_allocated)}</div>
                  <div><strong>Requested:</strong> {new Date(trip.created_at).toLocaleDateString()}</div>
                </div>

                <div className="content-card" style={{ marginTop: 8 }}>
                  <div className="page-title">💰 Budget Breakdown</div>
                  <div className="grid grid-2">
                    {Object.entries(trip.allocated_budget).map(([type, amount]) => (
                      <div key={type} className="card"><div className="grid" style={{ gridTemplateColumns: '1fr auto' }}><div className="text-muted">{type.replace('_', ' ').toUpperCase()}</div><div>{formatCurrency(amount)}</div></div></div>
                    ))}
                  </div>
                </div>

                <div className="action-buttons" style={{ marginTop: 12 }}>
                  <button className="btn btn-secondary" onClick={() => setSelectedTrip(trip)}>📋 Review & Approve</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {selectedTrip && (
        <div className="modal-overlay" onClick={() => setSelectedTrip(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>✅ Approve Trip Request</h3>
              <button onClick={() => setSelectedTrip(null)} className="close-btn">×</button>
            </div>
            <div className="modal-body">
              <div className="content-card">
                <div className="page-title">{selectedTrip.employee_name} - {selectedTrip.destination}</div>
                <div className="text-muted"><strong>Purpose:</strong> {selectedTrip.purpose}</div>
                <div className="text-muted"><strong>Duration:</strong> {selectedTrip.duration_days} days</div>
                <div className="text-muted"><strong>Dates:</strong> {new Date(selectedTrip.start_date).toLocaleDateString()} - {new Date(selectedTrip.end_date).toLocaleDateString()}</div>
              </div>

              <div className="content-card" style={{ marginTop: 12 }}>
                <div className="page-title">Budget Adjustments (Optional)</div>
                <div className="form">
                  {Object.entries(selectedTrip.allocated_budget).map(([type, originalAmount]) => (
                    <div key={type} className="form-group">
                      <label className="form-label">{type.replace('_', ' ').toUpperCase()}</label>
                      <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                        <span className="text-muted">Original: {formatCurrency(originalAmount)}</span>
                        <input className="form-control" type="number" placeholder={originalAmount} value={budgetAdjustments[type] || ''} onChange={(e) => handleBudgetAdjustment(type, e.target.value)} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="form" style={{ marginTop: 12 }}>
                <div className="form-group">
                  <label className="form-label">Approval Notes (Optional)</label>
                  <textarea className="form-control" rows="3" value={approvalNotes} onChange={(e) => setApprovalNotes(e.target.value)} placeholder="Add any notes or comments about this approval..."></textarea>
                </div>
              </div>

              <div className="action-buttons" style={{ justifyContent: 'flex-end', marginTop: 12 }}>
                <button onClick={() => setSelectedTrip(null)} className="btn btn-secondary">Cancel</button>
                <button onClick={() => handleApproveTrip(selectedTrip.trip_id)} className="btn btn-primary">✅ Approve Trip</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ManagerTripApprovals;
